[
  {
    "qid": "0004-t2i-1",
    "sample_id": "0004_阿金尼瀑布_0825ad12.jpg",
    "task": "t2i",
    "knowledge_dim": "geo_landmark",
    "difficulty": "L2",
    "evidence_audit": {
      "visible_facts": [
        "画面中心为从高处落下的白色水流",
        "水流经过多个岩石台阶并汇入至少两个蓝绿色水潭",
        "前景存在较低一级的跌水",
        "周围是茂密的深绿色森林植被",
        "岩体颜色偏浅，表面圆钝并带有湿润感",
        "整体环境为幽暗、狭窄的林间水道"
      ],
      "anchor_features": [
        "阿金尼瀑布具有多级连续落差的瀑布形态",
        "瀑布位于宿务岛的热带森林环境中",
        "浅色石灰岩台阶、蓝绿色水潭和连续跌水是该景观的主要识别特征"
      ],
      "trigger_check": "能。提示词明确给出阿金尼瀑布、宿务岛、自然风光和林间环境，模型可据此召回其多级石灰岩瀑布与蓝绿色水潭特征。",
      "counterexample_test": "尝试画成单一垂直落差、开阔河谷或人工水景都会与阿金尼瀑布的连续台阶、林间水道和石灰岩地貌锚点冲突，无法构成合理反例。"
    },
    "gen_prompt": "菲律宾宿务岛阿金尼瀑布，写实自然风光摄影，低机位横幅构图，主体居中偏上，水体呈明亮蓝绿色，树冠间洒下斑驳天光，营造潮湿、幽深、宁静的热带探险氛围，画面细节清晰，保留自然环境的纵深感。",
    "implicit_checks": [
      {
        "check": "主体水流沿浅色、圆钝的石灰岩台阶连续下降，至少形成三个清晰可辨的落差段",
        "knowledge": "[solid] 阿金尼瀑布以多级石灰岩瀑布和连续跌水为主要地貌识别特征；浅色、圆钝且受水流侵蚀的岩层符合其喀斯特河道形态",
        "verified": true,
        "weight": 0.4,
        "rubric": {
          "0": "没有可识别的连续水流，或只出现单一垂直落差与平直人工岩面",
          "1": "出现两级左右的水流落差，但岩体颜色、形态或连续台阶关系明显不足",
          "2": "可清楚看到至少三级连续落差，浅色圆钝石灰岩台阶与水流路径相互对应"
        },
        "acceptable_variants": [
          "部分台阶被水雾或植被遮挡，但仍能辨认三段连续下降关系",
          "采用侧面视角或近景构图，只要连续石灰岩落差结构清晰可判"
        ]
      },
      {
        "check": "画面中至少出现两个沿水流方向前后相连的蓝绿色水潭，并在更近处出现较小的后续跌水",
        "knowledge": "[solid] 阿金尼瀑布的典型景观由多级跌水、串联水潭和下游小落差共同组成；原图直接核实了这一空间结构",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "只出现一个水面，或水流直接进入开阔河道而没有串联水潭结构",
          "1": "出现两个水面但前后水域缺乏明确水流连接，或近处没有后续跌水",
          "2": "上游与下游至少两个水潭由水流连接，前景还能看到较小的后续跌水"
        },
        "acceptable_variants": [
          "广角远景中水潭面积较小，但前后串联关系仍然明确",
          "近景只展示部分水潭，只要能同时确认上游水域与前景小跌水"
        ]
      },
      {
        "check": "瀑布两侧被深色岩壁和浓密常绿植被包围，整体呈林间狭窄水道而非开阔平原",
        "knowledge": "[solid] 阿金尼瀑布位于菲律宾宿务岛热带森林中的岩石水道；原图直接显示两侧林木与暗色岩壁形成包围式环境",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "主体位于城市、公园设施或开阔平原，周围缺少连续森林与岩壁包围",
          "1": "有零散树木或岩石背景，但空间较开阔，无法形成两侧包围的林间水道",
          "2": "瀑布两侧均有连续深色岩壁和浓密常绿植被，视野明确收束在林间水道内"
        },
        "acceptable_variants": [
          "强烈逆光或局部遮挡导致一侧岩壁不明显，但另一侧与顶部植被仍形成明确包围感",
          "采用近距离特写，只要画面边缘保留森林和岩壁环境证据"
        ]
      }
    ],
    "facet_tags": [
      "landmark_identity",
      "nature_morphology",
      "real_world_scene",
      "composition"
    ],
    "gate_spec": {
      "required_subjects": [
        "阿金尼瀑布"
      ],
      "theme_definition": "宿务热带森林中的多级瀑布与串联水潭自然景观"
    },
    "expected_failure_modes": [
      "将阿金尼瀑布画成只有一道巨大垂直水帘的普通单级瀑布",
      "把浅色圆钝石灰岩台阶误画成黑色尖锐火山岩或规则混凝土结构",
      "只生成一个开阔湖泊或河流，缺少多个前后相连的水潭与前景跌水",
      "将场景放在稀疏草原、城市公园或缺少岩壁包围的开阔环境中"
    ],
    "notes": "利用阿金尼瀑布的多级石灰岩水道、串联水潭和热带林间形制构成地标识别探针。"
  }
]
